/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['pandas','python','xlsx2csv']:
 u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?onlyActiveTags=true&limit=50&page=1'
 try:
  with urllib.request.urlopen(u,timeout=30) as r:d=json.load(r)
  print(repo, [t['name'] for t in d.get('tags',[])[:12]])
 except Exception as e: print(repo,type(e).__name__)
PY"

/bin/bash -lc "python - <<'PY'
import json, urllib.request
for repo in ['pandas','python','xlsx2csv']:
 u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?onlyActiveTags=true&limit=50&page=1'
 try:
  with urllib.request.urlopen(u,timeout=30) as r:d=json.load(r)
  print(repo, [t['name'] for t in d.get('tags',[])[:12]])
 except Exception as e: print(repo,type(e).__name__)
PY"

